from __future__ import annotations

import json
import math
import sys
from pathlib import Path

import numpy as np
from pymatgen.analysis.local_env import CovalentRadius

TASK_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_ROOT / "source"
REPORT_PATH = TASK_ROOT / "outputs" / "public_reproduction_report.json"
CLOSURE_BUDGET = 0.2
CELL_VOLUME_RATIO_LIMIT = 2.0
CASES = [
    {
        "case_label": "public_lower_symmetry_etb_e",
        "topology_name": "etb-e",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_lower_symmetry_sra",
        "topology_name": "sra",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_lower_symmetry_unc",
        "topology_name": "unc",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_lower_symmetry_pts",
        "topology_name": "pts",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_lower_symmetry_tbo",
        "topology_name": "tbo",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_lower_symmetry_sod",
        "topology_name": "sod",
        "role": "lower_symmetry",
    },
    {
        "case_label": "public_pinned_control_pcu",
        "topology_name": "pcu",
        "role": "pinned_control",
    },
]


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_PATH.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def max_bond_error(framework) -> float:
    graph = framework.graph
    cell = np.asarray(graph.graph["cell"], dtype=float)
    inverse = np.linalg.inv(cell)
    errors: list[float] = []

    def target_bond_length(left: int, right: int) -> float:
        left_symbol = graph.nodes[left]["symbol"]
        right_symbol = graph.nodes[right]["symbol"]
        return float(CovalentRadius.radius[left_symbol] + CovalentRadius.radius[right_symbol])

    for left, right in graph.edges():
        if graph.nodes[left]["slot"] == graph.nodes[right]["slot"]:
            continue
        delta = np.asarray(graph.nodes[left]["coord"], dtype=float) - np.asarray(
            graph.nodes[right]["coord"], dtype=float
        )
        delta -= np.round(delta @ inverse) @ cell
        errors.append(abs(float(np.linalg.norm(delta)) - target_bond_length(left, right)))
    if not errors:
        raise ValueError("no inter-slot bonds were found in the public case")
    return max(errors)


def build_public_case(topology_name: str) -> tuple[object, object, float, float]:
    sys.path.insert(0, str(SOURCE_ROOT / "src"))
    from autografs import Autografs

    mofgen = Autografs()
    topology = mofgen.topologies[topology_name]
    building_units = mofgen.list_building_units(sieve=topology_name)
    mappings = {slot_type: options[0] for slot_type, options in building_units.items()}

    baseline = mofgen.build(topology, mappings=dict(mappings), max_rmsd=1.0)
    relaxed = mofgen.build(
        topology,
        mappings=dict(mappings),
        max_rmsd=1.0,
        relax_embedding=True,
    )
    return baseline, relaxed, max_bond_error(baseline), max_bond_error(relaxed)


def main() -> int:
    try:
        observations: list[dict[str, object]] = []
        for case in CASES:
            baseline, relaxed, baseline_error, relaxed_error = build_public_case(
                case["topology_name"]
            )
            baseline_volume = float(baseline.structure.volume)
            relaxed_volume = float(relaxed.structure.volume)
            error_delta = relaxed_error - baseline_error
            volume_delta = relaxed_volume - baseline_volume

            if not all(
                math.isfinite(value)
                for value in [
                    baseline_error,
                    relaxed_error,
                    baseline_volume,
                    relaxed_volume,
                    error_delta,
                    volume_delta,
                ]
            ):
                raise ValueError(
                    f"non-finite observation produced by the public case {case['case_label']}"
                )

            record: dict[str, object] = {
                "case_label": case["case_label"],
                "role": case["role"],
                "topology_name": case["topology_name"],
                "baseline_max_bond_error": baseline_error,
                "relaxed_max_bond_error": relaxed_error,
                "bond_error_delta": error_delta,
                "closure_budget": CLOSURE_BUDGET,
                "within_budget": relaxed_error <= baseline_error + CLOSURE_BUDGET,
                "budget_margin": baseline_error + CLOSURE_BUDGET - relaxed_error,
                "baseline_volume": baseline_volume,
                "relaxed_volume": relaxed_volume,
                "volume_delta": volume_delta,
                "volume_ratio": relaxed_volume / baseline_volume,
                "volume_ratio_limit": CELL_VOLUME_RATIO_LIMIT,
                "within_volume_budget": relaxed_volume
                <= baseline_volume * CELL_VOLUME_RATIO_LIMIT,
            }
            if case["role"] == "pinned_control":
                record["structure_unchanged"] = bool(
                    np.allclose(
                        baseline.structure.lattice.matrix,
                        relaxed.structure.lattice.matrix,
                    )
                    and np.allclose(
                        baseline.structure.cart_coords,
                        relaxed.structure.cart_coords,
                    )
                )
            observations.append(record)

        lower_symmetry_ok = all(
            bool(record["within_budget"] and record["within_volume_budget"])
            for record in observations
            if record["role"] == "lower_symmetry"
        )
        pinned_control = next(
            record for record in observations if record["role"] == "pinned_control"
        )
        pinned_ok = bool(pinned_control["structure_unchanged"])

        return write_report(
            {
                "schema_version": "1.0",
                "status": "post_fix_success" if lower_symmetry_ok and pinned_ok else "pre_fix_expected_failure",
                "observation": {
                    "cases": observations,
                    "lower_symmetry_ok": lower_symmetry_ok,
                    "pinned_control_ok": pinned_ok,
                },
            },
            0 if lower_symmetry_ok and pinned_ok else 1,
        )
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )


if __name__ == "__main__":
    raise SystemExit(main())

